
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rmsb86bl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rmsb86bl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.569127069782020e+00, -4.479447970935405e+00, -4.353839635085300e+00, -4.179955259079346e+00, -3.943262015041312e+00, -3.628779676235596e+00, -3.225203690189356e+00, -2.732358475026500e+00, -2.170390962881359e+00, -1.567549526706727e+00, -1.009446906283230e+00, -6.749894104829722e-01, -6.037950892314774e-01, -5.110562665878383e-01, -3.652829991342012e-01, -2.293079565688381e-01, -1.343083159774472e-01, -6.389504686451512e-02, -2.092994441589221e-02, -4.678538962147209e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


